}
.render-table .el-pagination span:not([class*=suffix]),
.render-table .el-pagination button {
  height: 24px;
  line-height: 24px;
}
.render-table .custom-table-header {
  position: absolute;
  right: 0px;
  top: var(----render-table--custom-table-header__top, -34px);
}
.render-table .custom-table-header .custom-table-header__btn {
  padding: 4px 0;
}
.render-table .vxe-table--body .vxe-body--row .vxe-body--column.col--ellipsis .render-pix-form-item-control-content-component {
  overflow: hidden;
  text-overflow: ellipsis;
