.el-popper .popper__arrow,
.el-popper .popper__arrow::after {
  position: absolute;
  display: block;
  width: 0;
  height: 0;
}
.el-popper .popper__arrow {
  border-width: 6px;
  filter: drop-shadow(0 2px 12px rgba(0, 0, 0, 0.03));
}
.el-popper .popper__arrow::after {
  content: " ";
  border-width: 6px;
}
.el-popper[x-placement^=top] {
  margin-bottom: 4px;
}
.el-popper[x-placement^=top] .popper__arrow {
  bottom: -6px;
  left: 50%;
  margin-right: calc(6px / 2);
}
.el-popper[x-placement^=top] .popper__arrow::after {
  bottom: 1px;
  margin-left: -6px;
}
.el-popper[x-placement^=bottom] {
  margin-top: 4px;
}
.el-popper[x-placement^=bottom] .popper__arrow {
  top: -6px;
  left: 50%;
  margin-right: calc(6px / 2);
}
.el-popper[x-placement^=bottom] .popper__arrow::after {
  top: 1px;
  margin-left: -6px;
}
.el-popper[x-placement^=right] {
  margin-left: 12px;
}
.el-popper[x-placement^=right] .popper__arrow {
  top: 50%;
  left: -6px;
  margin-bottom: calc(6px / 2);
}
.el-popper[x-placement^=right] .popper__arrow::after {
  bottom: -6px;
  left: 1px;
}
.el-popper[x-placement^=left] {
  margin-right: 12px;
}
.el-popper[x-placement^=left] .popper__arrow {
  top: 50%;
  right: -6px;
  margin-bottom: calc(6px / 2);
}
.el-popper[x-placement^=left] .popper__arrow::after {
  right: 1px;
  bottom: -6px;
  margin-left: -6px;
}
.el-select-dropdown {
  position: absolute;
  z-index: 1001;
  border-radius: 4px;
  background-color: #FFFFFF;
  box-shadow: 0 0 3px 0 rgba(0, 0, 0, 0.06), 0 6px 16px 0 rgba(0, 0, 0, 0.08), 0 9px 28px 8px rgba(0, 0, 0, 0.05);
  box-sizing: border-box;
  margin: 4px 0;
}
.el-select-dropdown .el-select-dropdown__item.selected {
  color: #0077FF;
  background-color: #FFFFFF;
}
.el-select-dropdown .is--medium .el-select-dropdown__item {
  font-size: 14px;
}
.el-select-dropdown.is-multiple .el-select-dropdown__item {
  padding-right: 40px;
}
.el-select-dropdown.is-multiple .el-select-dropdown__item.selected {
  color: #0077FF;
  background-color: #FFFFFF;
}
.el-select-dropdown.is-multiple .el-select-dropdown__item.selected::after {
  position: absolute;
  right: 20px;
  font-family: "element-icons";
  content: "\e6da";
  font-size: 12px;
  font-weight: bold;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: #0077FF;
}
.el-select-dropdown .el-scrollbar.is-empty .el-select-dropdown__list {
  padding: 0;
}
.el-select-dropdown .el-tree-node__content {
  border-radius: 0;
}
.el-select-dropdown__empty {
  padding: 10px 0;
  margin: 0;
  text-align: center;
  color: #999;
  font-size: 12px;
}
.el-select-dropdown__wrap {
  max-height: 274px;
}
.el-select-dropdown__list {
  list-style: none;
  padding: 6px 0;
  margin: 0;
  box-sizing: border-box;
}
