.v-modal-enter {
  animation: v-modal-in 0.2s ease;
}
.v-modal-leave {
  animation: v-modal-out 0.2s ease forwards;
}
@keyframes v-modal-in {
  0% {
    opacity: 0;
  }
}
@keyframes v-modal-out {
  100% {
    opacity: 0;
  }
}
.v-modal {
  position: fixed;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  opacity: 0.5;
  background: #000000;
}
.el-popup-parent--hidden {
  overflow: hidden;
}
.el-dialog {
  position: relative;
  margin: 0 auto 50px;
  background: #FFFFFF;
  border-radius: 2px;
  box-shadow: 0px 6px 16px -8px rgba(0, 0, 0, 0.08), 0px 9px 28px 0px rgba(0, 0, 0, 0.05), 0px 12px 48px 16px rgba(0, 0, 0, 0.03);
  box-sizing: border-box;
  width: 50%;
}
.el-dialog.is-fullscreen {
  width: 100%;
  margin-top: 0;
  margin-bottom: 0;
  height: 100%;
  overflow: auto;
}
.el-dialog__wrapper {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  overflow: auto;
  margin: 0;
}
.el-dialog__header {
  padding: 0 24px;
  border-bottom: 1px solid #E8E9EA;
  height: 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.el-dialog__headerbtn {
  position: absolute;
  top: 16px;
  right: 24px;
  padding: 0;
  background: transparent;
  border: none;
  outline: none;
  cursor: pointer;
  font-size: 16px;
}
.el-dialog__headerbtn .el-dialog__close {
  color: #96999C;
}
.el-dialog__headerbtn:focus .el-dialog__close, .el-dialog__headerbtn:hover .el-dialog__close {
  color: #161C24;
}
.el-dialog__title {
