.el-switch {
  display: inline-flex;
  align-items: center;
  position: relative;
  font-size: 12px;
  line-height: 22px;
  height: 22px;
  vertical-align: middle;
}
.el-switch.el-switch__loading.is-checked::before {
  position: absolute;
  content: "";
  right: 4px;
  left: auto;
  top: 4px;
  color: #FFFFFF;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: transparent;
  z-index: 1;
  border: 1px solid #0077FF;
  border-color: #0077FF #0077FF #0077FF transparent;
  animation: switch-loading 1s linear;
  animation-iteration-count: infinite;
}
.el-switch.el-switch__loading::before {
  position: absolute;
  content: "";
  left: 5px;
  top: 4px;
  color: #FFFFFF;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: transparent;
  z-index: 1;
  border: 1px solid #C5C6C8;
  border-color: #C5C6C8 #C5C6C8 #C5C6C8 transparent;
  animation: switch-loading 1s linear;
  animation-iteration-count: infinite;
}
.el-switch.el-switch__texts .el-switch__core {
  font-family: "pix-iconfont" !important;
}
.el-switch.el-switch__texts .el-switch__core::before {
  position: absolute;
  content: "关";
  right: 5px;
  top: -1px;
  color: #FFFFFF;
}
.el-switch.el-switch__texts.is-checked .el-switch__core::before {
  position: absolute;
  content: "开";
  left: 5px;
  top: -1px;
  color: #FFFFFF;
}
.el-switch.el-switch__icons .el-switch__core {
  font-family: "pix-iconfont" !important;
}
.el-switch.el-switch__icons .el-switch__core::before {
  position: absolute;
  content: "\e648";
  right: 5px;
  top: -1px;
  color: #FFFFFF;
}
.el-switch.el-switch__icons.is-checked .el-switch__core::before {
  position: absolute;
  content: "\e68d";
  left: 5px;
  top: -1px;
  color: #FFFFFF;
}
.el-switch.is-disabled .el-switch__core, .el-switch.is-disabled .el-switch__label {
  cursor: not-allowed;
}
.el-switch__label {
  transition: 0.2s;
  height: 22px;
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  vertical-align: middle;
  color: #7AC6FF;
}
.el-switch__label.is-active {
  color: #0077FF;
}
.el-switch__label--left {
  margin-right: 10px;
}
.el-switch__label--right {
  margin-left: 10px;
}
.el-switch__label * {
  line-height: 1;
  font-size: 12px;
  display: inline-block;
}
.el-switch__input {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0;
  margin: 0;
}
.el-switch__core {
  margin: 0;
  display: inline-block;
  position: relative;
  width: 44px;
  height: 22px;
  border: 1px solid #C5C6C8;
  outline: none;
  border-radius: 32px;
  box-sizing: border-box;
  background: #C5C6C8;
  cursor: pointer;
  transition: border-color 0.3s, background-color 0.3s;
  vertical-align: middle;
}
.el-switch__core:after {
  content: "";
  position: absolute;
  top: 1px;
  left: 2px;
  border-radius: 100%;
  transition: all 0.3s;
  width: 18px;
  height: 18px;
  background-color: #FFFFFF;
}
.el-switch.is-checked .el-switch__core {
  border-color: #0077FF;
  background-color: #0077FF;
}
.el-switch.is-checked .el-switch__core::after {
  left: 100%;
  margin-left: -19px;
}
.el-switch.is-disabled {
  opacity: 0.4;
}
.el-switch--small {
  height: 22px;
  line-height: 22px;
}
.el-switch--small:after {
  width: 18px;
  height: 18px;
}
.el-switch--small.is-checked .el-switch__core:after {
  margin-left: -19px;
}
.el-switch--mini {
  height: 16px;
