.el-loading-parent--relative {
  position: relative !important;
}
.el-loading-parent--hidden {
  overflow: hidden !important;
}
.el-loading-mask {
  position: absolute;
  z-index: 2000;
  background-color: rgba(255, 255, 255, 0.9);
  margin: 0;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  transition: opacity 0.3s;
}
.el-loading-mask.is-fullscreen {
  position: fixed;
}
.el-loading-mask.is-fullscreen .el-loading-spinner {
  margin-top: calc(-50px / 2);
}
.el-loading-mask.is-fullscreen .el-loading-spinner .circular {
  height: 50px;
  width: 50px;
}
.el-loading-spinner {
  top: 50%;
  margin-top: calc(-42px / 2);
  width: 100%;
  text-align: center;
  position: absolute;
}
.el-loading-spinner .el-loading-text {
  color: #51555B;
  margin: 6px 0;
  font-size: 14px;
}
.el-loading-spinner .circular {
  height: 42px;
  width: 42px;
  animation: loading-rotate 2s linear infinite;
}
.el-loading-spinner .path {
  animation: loading-dash 1.5s ease-in-out infinite;
  stroke-dasharray: 90, 150;
  stroke-dashoffset: 0;
  stroke-width: 2;
  stroke: #0077FF;
  stroke-linecap: round;
}
.el-loading-spinner i::before {
  color: #96999C;
  font-size: 20px;
}
.el-loading-fade-enter,
.el-loading-fade-leave-active {
  opacity: 0;
}
@keyframes loading-rotate {
  100% {
    transform: rotate(360deg);
  }
}
@keyframes loading-dash {
  0% {
    stroke-dasharray: 1, 200;
    stroke-dashoffset: 0;
  }
  50% {
    stroke-dasharray: 90, 150;
    stroke-dashoffset: -40px;
  }
  100% {
    stroke-dasharray: 90, 150;
    stroke-dashoffset: -120px;
  }
}
.el-spin {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-size: 14px;
  font-variant: tabular-nums;
  line-height: 1.5;
  list-style: none;
  font-feature-settings: "tnum";
  position: absolute;
  display: none;
  color: #0077FF;
  text-align: center;
  vertical-align: middle;
  opacity: 0;
  transition: transform 0.3s cubic-bezier(0.78, 0.14, 0.15, 0.86);
}
.el-spin-spinning {
  position: static;
  display: inline-block;
  opacity: 1;
}
.el-spin-dot {
  position: relative;
  display: inline-block;
  font-size: 24px;
  width: 1em;
  height: 1em;
}
.el-spin-dot-spin {
  transform: rotate(45deg);
  -webkit-animation: antRotate 1.2s linear infinite;
  animation: antRotate 1.2s linear infinite;
}
.iconLarge .el-spin-dot-item {
  width: 12px;
  height: 12px;
}
.iconLarge .el-spin-dot {
  font-size: 26px;
}
.iconLarge .el-loading-spinner i {
  font-size: 26px;
}
.iconLarge .el-loading-spinner .el-loading-text {
  margin-top: 6px;
}
.iconSmall .el-spin-dot-item {
  width: 6px;
  height: 6px;
}
.iconSmall .el-spin-dot {
  font-size: 14px;
}
.iconSmall .el-loading-spinner i {
  font-size: 14px;
}
.el-spin-dot-item {
  position: absolute;
  display: block;
  width: 9px;
  height: 9px;
  background-color: #0077FF;
  border-radius: 100%;
  transform: scale(0.9);
  transform-origin: 50% 50%;
  opacity: 0.3;
  -webkit-animation: antSpinMove 1s linear infinite alternate;
  animation: antSpinMove 1s linear infinite alternate;
}
.el-spin-dot-item:first-child {
  top: 0;
  left: 0;
}
.el-spin-dot-item:nth-child(2) {
  top: 0;
  right: 0;
  -webkit-animation-delay: 0.4s;
  animation-delay: 0.4s;
}
.el-spin-dot-item:nth-child(3) {
  right: 0;
  bottom: 0;
  -webkit-animation-delay: 0.8s;
  animation-delay: 0.8s;
}
.el-spin-dot-item:nth-child(4) {
  bottom: 0;
  left: 0;
  -webkit-animation-delay: 1.2s;
  animation-delay: 1.2s;
}
.textInline .el-loading-text {
  display: inline-block;
  margin-left: 10px;
}
@keyframes antSpinMove {
  to {
    opacity: 1;
  }
}
@keyframes antRotate {
  to {
    transform: rotate(405deg);
  }
