.el-radio__inner::after {
  width: 6px;
  height: 6px;
  border-radius: 100%;
  background-color: #FFFFFF;
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) scale(0);
}
