.el-checkbox {
  color: #161C24;
  font-weight: 400;
  font-size: 12px;
  position: relative;
  cursor: pointer;
  display: inline-block;
  white-space: nowrap;
  user-select: none;
  margin-right: 30px;
  line-height: 16px;
}
.el-checkbox.is-bordered {
  padding: 9px 20px 9px 10px;
  border-radius: 4px;
  border: 1px solid #B9BABD;
  box-sizing: border-box;
  line-height: normal;
  height: 40px;
}
.el-checkbox.is-bordered.is-checked {
  border-color: #0077FF;
}
.el-checkbox.is-bordered.is-disabled {
  border-color: #B9BABD;
  cursor: not-allowed;
}
.el-checkbox.is-bordered + .el-checkbox.is-bordered {
  margin-left: 10px;
}
.el-checkbox.is-bordered.el-checkbox--medium {
  padding: 7px 20px 7px 10px;
  border-radius: 2px;
  height: 36px;
}
.el-checkbox.is-bordered.el-checkbox--medium .el-checkbox__label {
  line-height: 17px;
  font-size: 14px;
}
.el-checkbox.is-bordered.el-checkbox--medium .el-checkbox__inner {
  height: 14px;
  width: 14px;
}
.el-checkbox.is-bordered.el-checkbox--small {
  padding: 5px 15px 5px 10px;
  border-radius: 2px;
  height: 32px;
}
.el-checkbox.is-bordered.el-checkbox--small .el-checkbox__label {
  line-height: 15px;
  font-size: 12px;
}
.el-checkbox.is-bordered.el-checkbox--small .el-checkbox__inner {
  height: 12px;
  width: 12px;
}
.el-checkbox.is-bordered.el-checkbox--small .el-checkbox__inner::after {
  height: 6px;
  width: 2px;
}
.el-checkbox.is-bordered.el-checkbox--mini {
  padding: 3px 15px 3px 10px;
  border-radius: 2px;
  height: 28px;
}
.el-checkbox.is-bordered.el-checkbox--mini .el-checkbox__label {
  line-height: 12px;
  font-size: 12px;
}
.el-checkbox.is-bordered.el-checkbox--mini .el-checkbox__inner {
  height: 12px;
  width: 12px;
}
.el-checkbox.is-bordered.el-checkbox--mini .el-checkbox__inner::after {
  height: 6px;
  width: 2px;
}
.el-checkbox__input {
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  display: inline-block;
  height: 16px;
  line-height: 1;
  position: relative;
  vertical-align: middle;
}
.el-checkbox__input.is-disabled .el-checkbox__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  cursor: not-allowed;
}
.el-checkbox__input.is-disabled .el-checkbox__inner::after {
  cursor: not-allowed;
  border-color: #C5C6C8;
}
.el-checkbox__input.is-disabled .el-checkbox__inner + .el-checkbox__label {
  cursor: not-allowed;
}
.el-checkbox__input.is-disabled.is-checked .el-checkbox__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  color: #B9BABD;
}
.el-checkbox__input.is-disabled.is-checked .el-checkbox__inner::after {
  border-color: #C5C6C8;
}
.el-checkbox__input.is-disabled.is-indeterminate .el-checkbox__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
}
.el-checkbox__input.is-disabled.is-indeterminate .el-checkbox__inner::before {
  background-color: #C5C6C8;
  border-color: #C5C6C8;
}
.el-checkbox__input.is-disabled + span.el-checkbox__label {
  color: #C5C6C8;
  cursor: not-allowed;
}
.el-checkbox__input.is-checked .el-checkbox__inner {
  background-color: #0077FF;
  border-color: #0077FF;
  color: #FFFFFF;
  text-align: center;
  display: flex;
}
.el-checkbox__input.is-checked .el-checkbox__inner::after {
  content: "\e68d";
  width: 100%;
  line-height: 120%;
}
.el-checkbox__input.is-focus {
  /*focus时 视觉上区分*/
}
.el-checkbox__input.is-indeterminate .el-checkbox__inner {
  background-color: #0077FF;
  border-color: #0077FF;
}
.el-checkbox__input.is-indeterminate .el-checkbox__inner::before {
  content: "";
  position: absolute;
  display: block;
  background-color: #FFFFFF;
  height: 2px;
  transform: scale(0.7);
  left: 0;
  right: 0;
  top: 6px;
}
.el-checkbox__input.is-indeterminate .el-checkbox__inner::after {
  display: none;
}
.el-checkbox__inner {
  display: inline-block;
  position: relative;
  border: 1px solid #B9BABD;
  border-radius: 2px;
  box-sizing: border-box;
  width: 16px;
  height: 16px;
  background-color: #FFFFFF;
  z-index: 1;
  transition: border-color 0.25s cubic-bezier(0.71, -0.46, 0.29, 1.46), background-color 0.25s cubic-bezier(0.71, -0.46, 0.29, 1.46);
  font-family: "pix-iconfont" !important;
}
.el-checkbox__inner:hover {
  border-color: #0077FF;
}
.el-checkbox__original {
  opacity: 0;
  outline: none;
  position: absolute;
  margin: 0;
  width: 0;
  height: 0;
  z-index: -1;
}
.el-checkbox__label {
  display: inline-block;
  padding-left: 8px;
  line-height: 16px;
  font-size: 12px;
  vertical-align: middle;
}
.el-checkbox:last-of-type {
  margin-right: 0;
}
.el-checkbox-button {
  position: relative;
  display: inline-block;
}
.el-checkbox-button__inner {
  display: inline-block;
  line-height: 1;
  font-weight: 400;
  white-space: nowrap;
  vertical-align: middle;
  cursor: pointer;
  background: #FFFFFF;
  border: 1px solid #B9BABD;
  border-left: 0;
  color: #161C24;
  -webkit-appearance: none;
  text-align: center;
  box-sizing: border-box;
  outline: none;
  margin: 0;
  position: relative;
  transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);
  -moz-user-select: none;
  -webkit-user-select: none;
  -ms-user-select: none;
  padding: 7px 15px;
  font-size: 12px;
  border-radius: 0;
}
.el-checkbox-button__inner.is-round {
  padding: 7px 15px;
  border-radius: 20px;
}
.el-checkbox-button__inner:hover {
  color: #0077FF;
  border-color: #0077FF;
}
.el-checkbox-button__inner [class*=el-icon-] {
  line-height: 0.9;
}
.el-checkbox-button__inner [class*=el-icon-] + span {
  margin-left: 5px;
}
.el-checkbox-button__original {
  opacity: 0;
  outline: none;
  position: absolute;
  margin: 0;
  z-index: -1;
}
.el-checkbox-button.is-checked .el-checkbox-button__inner {
  color: #FFFFFF;
  background-color: #0077FF;
  border-color: #0077FF;
  box-shadow: -1px 0 0 0 #FFFFFF;
}
.el-checkbox-button.is-checked:first-child .el-checkbox-button__inner {
  border-left-color: #0077FF;
}
.el-checkbox-button:first-child .el-checkbox-button__inner {
  border-left: 1px solid #B9BABD;
  border-radius: 4px 0 0 4px;
  box-shadow: none !important;
}
.el-checkbox-button:first-child .el-checkbox-button__inner:hover {
  border-color: #0077FF;
}
.el-checkbox-button.is-disabled .el-checkbox-button__inner {
  color: #C5C6C8;
  cursor: not-allowed;
  background-image: none;
  background-color: #F6F6F6;
  border-color: #B9BABD;
  box-shadow: none;
}
.el-checkbox-button.is-disabled:first-child .el-checkbox-button__inner {
  border-color: #B9BABD;
}
.el-checkbox-button:not(:first-child):hover {
  color: #7AC6FF;
  border-color: #7AC6FF;
}
.el-checkbox-button:not(:first-child):hover::before {
  content: "";
  position: absolute;
  left: -1px;
  top: 0;
  z-index: 0;
  height: 100%;
  width: 1px;
  background-color: #7AC6FF;
}
.el-checkbox-button.is-disabled:not(:first-child):hover {
  border-color: #B9BABD;
}
.el-checkbox-button.is-disabled:not(:first-child):hover::before {
  background-color: #B9BABD;
  z-index: -1;
}
.el-checkbox-button:last-child .el-checkbox-button__inner {
  border-radius: 0 4px 4px 0;
}
.el-checkbox-button--medium .el-checkbox-button__inner {
  padding: 8px 15px;
  font-size: 14px;
  border-radius: 0;
}
.el-checkbox-button--medium .el-checkbox-button__inner.is-round {
  padding: 8px 15px;
  border-radius: 20px;
}
.el-checkbox-button--small .el-checkbox-button__inner {
  padding: 7px 15px;
  font-size: 12px;
  border-radius: 0;
}
.el-checkbox-button--small .el-checkbox-button__inner.is-round {
  padding: 7px 15px;
  border-radius: 20px;
}
.el-checkbox-button--mini .el-checkbox-button__inner {
  padding: 5px 7px;
  font-size: 12px;
  border-radius: 0;
}
.el-checkbox-button--mini .el-checkbox-button__inner.is-round {
  padding: 5px 7px;
  border-radius: 20px;
}
.el-checkbox-group {
  font-size: 0;
}
