.el-tag {
  background-color: #E6F6FF;
  border-color: #2994FF;
  color: #0077FF;
  display: inline-block;
  height: 22px;
  padding: 0 8px;
  line-height: 20px;
  font-size: 12px;
  color: #0077FF;
  border-width: 1px;
  border-style: solid;
  border-radius: 2px;
  box-sizing: border-box;
  white-space: nowrap;
  position: relative;
}
.el-tag .el-tag__close {
  margin-left: 4px;
  color: #0077ff;
}
.el-tag.el-tag--info {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  color: #161C24;
}
.el-tag.el-tag--info .el-tag__close {
  color: #96999c;
}
.el-tag.el-tag--success {
  background-color: #F6FBF4;
  border-color: #A8DD92;
  color: #52C718;
}
.el-tag.el-tag--success .el-tag__close {
  color: #52c718;
}
.el-tag.el-tag--warning {
  background-color: #FEFAF4;
  border-color: #FAD295;
  color: #FAAE16;
}
.el-tag.el-tag--warning .el-tag__close {
  color: #faae16;
}
.el-tag.el-tag--danger {
  background-color: #FEF5F6;
  border-color: #FB9EA3;
  color: #FF4A4D;
}
.el-tag.el-tag--danger .el-tag__close {
  color: #ff4a4d;
}
.el-tag.disabled {
  opacity: 0.4;
}
.el-tag.el-tag--dark__top:after {
  position: absolute;
  display: block;
  content: "";
  width: 0;
  height: 0;
  left: 50%;
  top: -12px;
  transform: translateX(-50%);
  border-color: transparent transparent #0077FF transparent;
  border-style: solid;
  border-width: 6px;
}
.el-tag.el-tag--dark__bottom:after {
  position: absolute;
  display: block;
  content: "";
  width: 0;
  height: 0;
  left: 50%;
  bottom: -12px;
  transform: translateX(-50%);
  border-color: #0077FF transparent transparent transparent;
  border-style: solid;
  border-width: 6px;
}
.el-tag.el-tag--dark__left:after {
  position: absolute;
  display: block;
  content: "";
  width: 0;
  height: 0;
  left: -12px;
  top: 50%;
  transform: translateY(-50%);
  border-color: transparent #0077FF transparent transparent;
  border-style: solid;
  border-width: 6px;
}
.el-tag.el-tag--dark__right:after {
  position: absolute;
  display: block;
  content: "";
  width: 0;
  height: 0;
  right: -12px;
  top: 50%;
  transform: translateY(-50%);
  border-color: transparent transparent transparent #0077FF;
  border-style: solid;
  border-width: 6px;
}
.el-tag [class^=el-icon-] {
  margin-right: 4px;
}
.el-tag .el-icon-close {
  border-radius: 50%;
  text-align: center;
  position: relative;
  cursor: pointer;
  font-size: 12px;
  height: 14px;
  width: 14px;
  line-height: 14px;
  vertical-align: middle;
  top: -1px;
}
.el-tag .el-icon-close::before {
  content: "\e648";
}
.el-tag.el-tag--dark {
  background-color: #0077FF;
  border-color: #0077FF;
  color: #FFFFFF;
}
.el-tag.el-tag--dark .el-tag__close {
  color: #FFFFFF;
