}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__left:after {
  border-color: transparent #FAAE16 transparent transparent;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__right:after {
  border-color: transparent transparent transparent #FAAE16;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__top:after {
