}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__left:after {
  border-color: transparent #FF4A4D transparent transparent;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__right:after {
  border-color: transparent transparent transparent #FF4A4D;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__top:after {
  border-color: transparent transparent #FF4A4D transparent;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__bottom:after {
  border-color: #FF4A4D transparent transparent transparent;
}
.el-tag.el-tag--dark.el-tag--danger .el-tag__close {
  color: #FFFFFF;
}
.el-tag.el-tag--dark.disabled {
