  content: "\e6da";
  right: -3px;
  bottom: -3px;
  font-size: 12px;
  line-height: 1;
  color: #ffffff;
  transform: scale(0.7);
}
.el-tag.el-tag--plain.el-tag--info {
  background-color: #FFFFFF;
  border-color: #B9BABD;
}
.el-tag.el-tag--plain.el-tag--info.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #B9BABD;
}
.el-tag.el-tag--plain.el-tag--success {
  background-color: #FFFFFF;
  border-color: #52C718;
}
.el-tag.el-tag--plain.el-tag--success.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #52C718;
