.el-textarea {
  position: relative;
  display: inline-block;
  width: 100%;
  vertical-align: bottom;
  font-size: 12px;
}
.el-textarea__inner {
  display: block;
  resize: vertical;
  padding: 5px 12px;
  line-height: 1.5;
  box-sizing: border-box;
  width: 100%;
  font-size: inherit;
  color: #161C24;
  background-color: #FFFFFF;
  background-image: none;
  border: 1px solid #B9BABD;
  border-radius: 2px;
  transition: border-color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.el-textarea__inner::placeholder {
  color: #C5C6C8;
}
.el-textarea__inner:hover {
  border-color: #73777C;
  color: #73777C;
}
.el-textarea__inner:hover::placeholder {
  color: #C5C6C8;
}
.el-textarea__inner:focus {
  outline: none;
  border-color: #0077FF;
}
.el-textarea .el-input__count {
  color: #96999C;
  background: #FFFFFF;
  position: absolute;
  font-size: 12px;
  bottom: 5px;
  right: 10px;
}
.el-textarea .el-input__count-limit {
  color: #FF4A4D;
}
.el-textarea.is-disabled .el-textarea__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  color: #161C24;
  cursor: not-allowed;
}
.el-textarea.is-disabled .el-textarea__inner::placeholder {
  color: #C5C6C8;
}
.el-textarea.is-exceed .el-textarea__inner {
  border-color: #FF4A4D;
}
.el-textarea.is-exceed .el-input__count {
  color: #FF4A4D;
}
.el-input {
  position: relative;
  font-size: 12px;
  display: inline-block;
  width: 100%;
}
.el-input::-webkit-scrollbar {
  z-index: 11;
  width: 6px;
}
.el-input::-webkit-scrollbar:horizontal {
  height: 6px;
}
.el-input::-webkit-scrollbar-thumb {
  border-radius: 5px;
  width: 6px;
  background: #b4bccc;
}
.el-input::-webkit-scrollbar-corner {
  background: #fff;
}
.el-input::-webkit-scrollbar-track {
  background: #fff;
}
.el-input::-webkit-scrollbar-track-piece {
  background: #fff;
  width: 6px;
}
.el-input .el-input__clear {
  color: #96999C;
  cursor: pointer;
  transition: color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.el-input .el-input__count {
  height: 100%;
  display: inline-flex;
  align-items: center;
  color: #96999C;
  font-size: 12px;
}
.el-input .el-input__count .el-input__count-inner {
  background: #FFFFFF;
  line-height: initial;
  display: inline-block;
  padding: 0 5px;
}
.el-input .el-input__count .el-input__count-limit {
  color: #FF4A4D;
}
.el-input__inner {
  -webkit-appearance: none;
  background-color: #FFFFFF;
  background-image: none;
  border-radius: 2px;
  border: 1px solid #B9BABD;
  box-sizing: border-box;
  color: #161C24;
  display: inline-block;
  font-size: inherit;
  height: 28px;
  line-height: 28px;
  outline: none;
  padding: 0 12px;
  transition: border-color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
  width: 100%;
}
.el-input__inner::-ms-reveal {
  display: none;
}
.el-input__inner::placeholder {
  color: #C5C6C8;
}
.el-input__inner:hover {
  border-color: #73777C;
}
.el-input__inner:focus {
  outline: none;
  border-color: #0077FF;
}
.el-input__suffix {
  position: absolute;
  height: 100%;
  right: 5px;
  top: 0;
  text-align: center;
  color: #96999C;
  transition: all 0.3s;
  pointer-events: none;
}
.el-input__suffix .el-icon-loading:before {
  color: #96999C;
}
.el-input__suffix .el-icon__danger_color {
  color: #FF4A4D;
}
.el-input__suffix .el-icon__warning_color {
  color: #FAAE16;
}
.el-input__suffix .el-icon__success_color {
  color: #52C718;
}
.el-input__suffix-inner {
  pointer-events: all;
}
.el-input__prefix {
  position: absolute;
  height: 100%;
  left: 5px;
  top: 0;
  text-align: center;
  color: #96999C;
  transition: all 0.3s;
}
.el-input__icon {
  height: 100%;
  width: 25px;
  text-align: center;
  transition: all 0.3s;
  line-height: 28px;
}
.el-input__icon:after {
  content: "";
  height: 100%;
  width: 0;
  display: inline-block;
  vertical-align: middle;
}
.el-input__validateIcon {
  pointer-events: none;
}
.el-input.is-active .el-input__inner {
  outline: none;
  border-color: #0077FF;
}
.el-input.is-disabled .el-input__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  color: #161C24;
  cursor: not-allowed;
}
.el-input.is-disabled .el-input__inner::placeholder {
  color: #C5C6C8;
}
.el-input.is-disabled .el-input__icon {
  cursor: not-allowed;
}
.el-input.is-exceed .el-input__inner {
  border-color: #FF4A4D;
}
.el-input.is-exceed .el-input__suffix .el-input__count {
  color: #FF4A4D;
}
.el-input--suffix .el-input__inner {
  padding-right: 30px;
}
.el-input--prefix .el-input__inner {
  padding-left: 30px;
}
.el-input--medium {
  font-size: 14px;
}
.el-input--medium .el-input__inner {
  height: 32px;
  line-height: 32px;
}
.el-input--medium .el-input__icon {
  line-height: 32px;
}
.el-input--small {
  font-size: 12px;
}
.el-input--small .el-input__inner {
  height: 28px;
  line-height: 28px;
}
.el-input--small .el-input__icon {
  line-height: 28px;
}
.el-input--mini {
  font-size: 12px;
}
.el-input--mini .el-input__inner {
  height: 24px;
  line-height: 24px;
}
.el-input--mini .el-input__icon {
  line-height: 24px;
}
.el-input.input-search-primary .el-input-group__append {
  background-color: #0077FF;
  border-color: #0077FF;
}
.el-input.input-search-primary .el-input-group__append button.el-button {
  color: #FFFFFF;
}
.el-input.input-white-select .el-input-group__append {
  background-color: #FFFFFF;
}
.el-input.input-white-select .el-input-group__prepend {
  background-color: #FFFFFF;
}
.el-input-group {
  line-height: normal;
  display: inline-table;
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}
.el-input-group > .el-input__inner {
  vertical-align: middle;
  display: table-cell;
}
.el-input-group__append, .el-input-group__prepend {
  background-color: #FFFFFF;
  color: #51555B;
  vertical-align: middle;
  display: table-cell;
  position: relative;
  border: 1px solid #B9BABD;
  border-radius: 2px;
  padding: 0 16px;
  width: 1px;
  white-space: nowrap;
}
.el-input-group__append:focus, .el-input-group__prepend:focus {
  outline: none;
}
.el-input-group__append .el-select,
.el-input-group__append .el-button, .el-input-group__prepend .el-select,
.el-input-group__prepend .el-button {
  display: inline-block;
  margin: -10px -20px;
}
.el-input-group__append button.el-button,
.el-input-group__append div.el-select .el-input__inner,
.el-input-group__append div.el-select:hover .el-input__inner, .el-input-group__prepend button.el-button,
.el-input-group__prepend div.el-select .el-input__inner,
.el-input-group__prepend div.el-select:hover .el-input__inner {
  border-color: transparent;
  background-color: transparent;
  color: #51555B;
  border-top: 0;
  border-bottom: 0;
}
.el-input-group__append .el-button,
.el-input-group__append .el-input, .el-input-group__prepend .el-button,
.el-input-group__prepend .el-input {
  font-size: inherit;
}
.el-input-group__prepend {
  border-right: 0;
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}
.el-input-group__append {
  border-left: 0;
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}
.el-input-group--prepend .el-input__inner {
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
  color: #51555B;
}
.el-input-group--prepend .el-select .el-input.is-focus .el-input__inner {
  border-color: transparent;
  color: #C5C6C8;
}
.el-input-group--append .el-input__inner {
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
  color: #51555B;
}
.el-input-group--append .el-select .el-input.is-focus .el-input__inner {
  border-color: transparent;
  color: #C5C6C8;
}
/** disalbe default clear on IE */
.el-input__inner::-ms-clear {
  display: none;
  width: 0;
  height: 0;
}
.el-input-group .el-input__inner:focus {
  box-shadow: none;
}
.el-input__danger .el-input__inner {
  border-color: #FF4A4D;
}
.el-input__warning .el-input__inner {
  border-color: #FAAE16;
}
.el-input__suffix .el-icon-circle-close {
  font-size: 14px;
  color: #C5C6C8;
  cursor: pointer;
}
