  border-color: transparent #F1F2F2 transparent transparent;
}
.el-tag.el-tag--dark.el-tag--info.el-tag--dark__right:after {
  border-color: transparent transparent transparent #F1F2F2;
}
.el-tag.el-tag--dark.el-tag--info.el-tag--dark__top:after {
  border-color: transparent transparent #F1F2F2 transparent;
}
.el-tag.el-tag--dark.el-tag--info.el-tag--dark__bottom:after {
  border-color: #F1F2F2 transparent transparent transparent;
}
.el-tag.el-tag--dark.el-tag--info .el-tag__close {
  color: #96999C;
}
.el-tag.el-tag--dark.el-tag--success {
  background-color: #52C718;
  border-color: #52C718;
  color: #FFFFFF;
}
.el-tag.el-tag--dark.el-tag--success.el-tag--dark__left:after {
  border-color: transparent #52C718 transparent transparent;
}
.el-tag.el-tag--dark.el-tag--success.el-tag--dark__right:after {
