.el-tag.el-tag--dark.el-tag--success.el-tag--dark__top:after {
  border-color: transparent transparent #52C718 transparent;
}
.el-tag.el-tag--dark.el-tag--success.el-tag--dark__bottom:after {
  border-color: #52C718 transparent transparent transparent;
}
.el-tag.el-tag--dark.el-tag--success .el-tag__close {
  color: #FFFFFF;
}
.el-tag.el-tag--dark.el-tag--warning {
  background-color: #FAAE16;
  border-color: #FAAE16;
  color: #FFFFFF;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__left:after {
  border-color: transparent #FAAE16 transparent transparent;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__right:after {
  border-color: transparent transparent transparent #FAAE16;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__top:after {
  border-color: transparent transparent #FAAE16 transparent;
}
.el-tag.el-tag--dark.el-tag--warning.el-tag--dark__bottom:after {
  border-color: #FAAE16 transparent transparent transparent;
}
.el-tag.el-tag--dark.el-tag--warning .el-tag__close {
  color: #FFFFFF;
}
.el-tag.el-tag--dark.el-tag--danger {
  background-color: #FF4A4D;
  border-color: #FF4A4D;
  color: #FFFFFF;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__left:after {
  border-color: transparent #FF4A4D transparent transparent;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__right:after {
  border-color: transparent transparent transparent #FF4A4D;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__top:after {
  border-color: transparent transparent #FF4A4D transparent;
}
.el-tag.el-tag--dark.el-tag--danger.el-tag--dark__bottom:after {
  border-color: #FF4A4D transparent transparent transparent;
}
.el-tag.el-tag--dark.el-tag--danger .el-tag__close {
