.el-tag.el-tag--plain {
  border-color: #0077FF;
  background-color: #FFFFFF;
}
.el-tag.el-tag--plain.el-tag--plain__bottom-right {
  position: relative;
  font-family: element-icons !important;
}
.el-tag.el-tag--plain.el-tag--plain__bottom-right:before {
  position: absolute;
  display: block;
  content: "";
  width: 0;
  height: 0;
  right: 0;
  bottom: 0;
  border-bottom: 12px solid #0077FF;
  border-left: 12px solid transparent;
}
.el-tag.el-tag--plain.el-tag--plain__bottom-right:after {
  position: absolute;
  content: "\e6da";
  right: -3px;
  bottom: -3px;
  font-size: 12px;
  line-height: 1;
  color: #ffffff;
  transform: scale(0.7);
}
.el-tag.el-tag--plain.el-tag--info {
  background-color: #FFFFFF;
  border-color: #B9BABD;
}
.el-tag.el-tag--plain.el-tag--info.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #B9BABD;
}
.el-tag.el-tag--plain.el-tag--success {
  background-color: #FFFFFF;
  border-color: #52C718;
}
.el-tag.el-tag--plain.el-tag--success.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #52C718;
}
.el-tag.el-tag--plain.el-tag--warning {
  background-color: #FFFFFF;
  border-color: #FAAE16;
}
.el-tag.el-tag--plain.el-tag--warning.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #FAAE16;
}
.el-tag.el-tag--plain.el-tag--danger {
  background-color: #FFFFFF;
  border-color: #FF4A4D;
}
.el-tag.el-tag--plain.el-tag--danger.el-tag--plain__bottom-right:before {
  border-bottom: 12px solid #FF4A4D;
}
.el-tag.el-tag--plain.disabled {
  opacity: 0.4;
}
.el-tag--medium {
  height: 28px;
  line-height: 26px;
}
.el-tag--medium .el-icon-close {
  transform: scale(0.8);
}
.el-tag--small {
  height: 22px;
  padding: 0 8px;
  line-height: 20px;
}
.el-tag--small .el-icon-close {
  transform: scale(0.8);
}
.el-tag--mini {
  height: 20px;
  padding: 0 5px;
  line-height: 18px;
}
.el-tag--mini .el-icon-close {
  margin-left: -3px;
  transform: scale(0.7);
}
