}
.el-step__head.is-success {
  color: #FFFFFF;
  border-color: #52C718;
}
.el-step__head.is-success .el-step__icon {
  background: #52C718;
}
.el-step__head.is-error {
  color: #FF4A4D;
  border-color: #FF4A4D;
}
.el-step__head.is-error .el-step__icon {
  background: #FFFFFF;
}
.el-step__head.is-finish {
  color: #0077FF;
  border-color: #0077FF;
}
.el-step__head.is-finish .el-step__icon {
  background: #FFFFFF;
}
.el-step__icon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  font-size: 16px;
  box-sizing: border-box;
  background: #C5C6C8;
  transition: 0.15s ease-out;
}
.el-step__icon.is-text {
  border-radius: 50%;
  border: 1px solid;
  border-color: inherit;
}
.el-step__icon.is-icon {
  width: 40px;
}
.el-step__icon-inner {
  display: inline-block;
  user-select: none;
  text-align: center;
  line-height: 1;
  color: inherit;
}
.el-step__icon-inner[class*=el-icon]:not(.is-status) {
  font-size: 25px;
  font-weight: normal;
}
.el-step__icon-inner.is-status {
  transform: translateY(1px);
}
.el-step__line {
  position: absolute;
  border-color: inherit;
  background-color: #E8E9EA;
}
.el-step__line-inner {
  display: block;
  transition: 0.15s ease-out;
  box-sizing: border-box;
  width: 0;
  height: 0;
}
.el-step__main {
  white-space: normal;
  text-align: left;
}
.el-step__title {
  font-size: 14px;
  line-height: 38px;
}
.el-step__title.is-process {
  font-weight: bold;
  color: #161C24;
}
.el-step__title.is-wait {
  color: #96999C;
}
.el-step__title.is-success {
  color: #161C24;
}
.el-step__title.is-error {
  color: #FF4A4D;
}
.el-step__title.is-finish {
  color: #161C24;
}
.el-step__description {
  padding-right: 10%;
  margin-top: -5px;
  font-size: 12px;
  line-height: 20px;
  font-weight: normal;
}
.el-step__description.is-process {
  color: #161C24;
}
.el-step__description.is-wait {
  color: #C5C6C8;
}
.el-step__description.is-success {
  color: #161C24;
}
.el-step__description.is-error {
  color: #FF4A4D;
}
.el-step__description.is-finish {
  color: #161C24;
}
.el-step.is-horizontal {
  display: inline-block;
}
.el-step.is-horizontal .el-step__line {
  height: 1px;
  top: 16px;
  left: 40px;
  right: 8px;
}
.el-step.is-vertical {
  display: flex;
}
.el-step.is-vertical .el-step__head {
  flex-grow: 0;
  width: 24px;
}
.el-step.is-vertical .el-step__main {
  padding-left: 16px;
  flex-grow: 1;
}
.el-step.is-vertical .el-step__title {
  line-height: 24px;
  padding-bottom: 8px;
}
.el-step.is-vertical .el-step__line {
  width: 1px;
  top: 40px;
  bottom: 8px;
  left: 16px;
}
.el-step.is-vertical .el-step__icon.is-icon {
  width: 24px;
}
.el-step.is-center .el-step__head {
  text-align: center;
}
.el-step.is-center .el-step__main {
  text-align: center;
}
.el-step.is-center .el-step__description {
  padding-left: 20%;
  padding-right: 20%;
}
.el-step.is-center .el-step__line {
  left: 60%;
  right: -40%;
}
.el-step.is-simple {
  display: flex;
  align-items: center;
}
.el-step.is-simple .el-step__head {
  width: auto;
  font-size: 0;
  padding-right: 10px;
}
.el-step.is-simple .el-step__icon {
  background: transparent;
  width: 16px;
  height: 16px;
  font-size: 12px;
}
.el-step.is-simple .el-step__icon-inner[class*=el-icon]:not(.is-status) {
  font-size: 18px;
}
.el-step.is-simple .el-step__icon-inner.is-status {
  transform: scale(0.8) translateY(1px);
}
.el-step.is-simple .el-step__main {
  position: relative;
  display: flex;
  align-items: stretch;
  flex-grow: 1;
}
.el-step.is-simple .el-step__title {
  font-size: 16px;
  line-height: 20px;
}
.el-step.is-simple:not(:last-of-type) .el-step__title {
  max-width: 50%;
  word-break: break-all;
}
.el-step.is-simple .el-step__arrow {
  flex-grow: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.el-step.is-simple .el-step__arrow::before, .el-step.is-simple .el-step__arrow::after {
  content: "";
  display: inline-block;
  position: absolute;
  height: 15px;
  width: 1px;
  background: #C5C6C8;
}
.el-step.is-simple .el-step__arrow::before {
  transform: rotate(-45deg) translateY(-4px);
  transform-origin: 0 0;
}
.el-step.is-simple .el-step__arrow::after {
  transform: rotate(45deg) translateY(4px);
  transform-origin: 100% 100%;
}
.el-step.is-simple:last-of-type .el-step__arrow {
  display: none;
}
.el-icons-steps .el-step__icon {
  background: none !important;
}
.el-icons-steps .el-step__head.is-process {
  color: #0077FF;
}
.el-icons-steps .el-step__head.is-wait {
  color: #C5C6C8;
