}
.el-tree {
  position: relative;
  cursor: default;
  background: #FFFFFF;
  color: #161C24;
}
.el-tree__empty-block {
  position: relative;
  min-height: 60px;
  text-align: center;
  width: 100%;
  height: 100%;
}
.el-tree__empty-text {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #161C24;
  font-size: 12px;
}
.el-tree__drop-indicator {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background-color: #0077FF;
}
.el-tree-node {
  white-space: nowrap;
  outline: none;
}
.el-tree-node .el-checkbox__input.is-disabled.is-checked .el-checkbox__inner {
  color: #C5C6C8;
}
.el-tree-node:focus { /* focus */ }
.el-tree-node.is-drop-inner > .el-tree-node__content .el-tree-node__label {
  background-color: #0077FF;
  color: #fff;
}
.el-tree-node__content {
  display: flex;
  align-items: center;
  height: 36px;
  border-radius: 4px;
  cursor: pointer;
}
.el-tree-node__content > .el-tree-node__expand-icon {
  padding: 6px;
}
.el-tree-node__content > label.el-checkbox {
  margin-right: 2px;
}
.el-tree-node__content > label.el-checkbox.is-disabled ~ .el-tree-node__label {
  color: #C5C6C8;
}
.el-tree-node__content:hover {
  background-color: #F6F6F6;
}
.el-tree.is-dragging .el-tree-node__content {
  cursor: move;
}
.el-tree.is-dragging .el-tree-node__content * {
  pointer-events: none;
}
.el-tree.is-dragging.is-drop-not-allow .el-tree-node__content {
  cursor: not-allowed;
}
.el-tree-node__expand-icon {
  cursor: pointer;
  color: #51555B;
  font-size: 12px;
  transform: rotate(0deg);
  transition: transform 0.3s ease-in-out;
}
.el-tree-node__expand-icon.expanded {
  transform: rotate(90deg);
}
.el-tree-node__expand-icon.is-leaf {
  color: transparent;
  cursor: default;
}
.el-tree-node__expand-icon + .el-tree-node__custom-icon {
  padding-left: 0;
}
.el-tree-node__custom-icon {
  display: flex;
  align-items: center;
  padding: 0 8px;
  font-size: 14px;
}
.el-tree-node__custom-icon > i, .el-tree-node__custom-icon > img {
  width: 14px;
  height: 14px;
}
.el-tree-node__custom-icon + .el-tree-node__label {
  padding-left: 0;
}
.el-tree-node__label {
  font-size: 12px;
  padding: 0 4px;
  border-radius: 4px;
  line-height: 36px;
  width: 100%;
}
.el-tree-node__loading-icon {
  margin-right: 8px;
  font-size: 12px;
  color: #C5C6C8;
  position: absolute;
  left: 5px;
  background: #FFFFFF;
}
.el-tree-node > .el-tree-node__children {
  overflow: hidden;
  background-color: transparent;
}
.el-tree-node.is-expanded > .el-tree-node__children {
  display: block;
}
.el-tree--highlight-current .el-tree-node.is-current > .el-tree-node__content {
  background-color: #ebf4ff;
}
.el-tree-node.is-current > .el-tree-node__content {
  background: #E6F6FF;
}
.el-tree-node.is-current > .el-tree-node__content .el-tree-node__label {
  color: #0077FF;
