.el-textarea {
  position: relative;
  display: inline-block;
  width: 100%;
  vertical-align: bottom;
  font-size: 12px;
}
.el-textarea__inner {
  display: block;
  resize: vertical;
  padding: 5px 12px;
  line-height: 1.5;
  box-sizing: border-box;
  width: 100%;
  font-size: inherit;
  color: #161C24;
  background-color: #FFFFFF;
  background-image: none;
  border: 1px solid #B9BABD;
  border-radius: 2px;
  transition: border-color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.el-textarea__inner::placeholder {
  color: #C5C6C8;
}
.el-textarea__inner:hover {
  border-color: #73777C;
  color: #73777C;
}
.el-textarea__inner:hover::placeholder {
  color: #C5C6C8;
}
.el-textarea__inner:focus {
  outline: none;
  border-color: #0077FF;
}
.el-textarea .el-input__count {
  color: #96999C;
  background: #FFFFFF;
  position: absolute;
  font-size: 12px;
  bottom: 5px;
  right: 10px;
}
.el-textarea .el-input__count-limit {
  color: #FF4A4D;
}
.el-textarea.is-disabled .el-textarea__inner {
  background-color: #F6F6F6;
  border-color: #B9BABD;
  color: #161C24;
  cursor: not-allowed;
}
.el-textarea.is-disabled .el-textarea__inner::placeholder {
  color: #C5C6C8;
}
.el-textarea.is-exceed .el-textarea__inner {
  border-color: #FF4A4D;
}
.el-textarea.is-exceed .el-input__count {
  color: #FF4A4D;
}
.el-input {
  position: relative;
  font-size: 12px;
  display: inline-block;
  width: 100%;
}
.el-input::-webkit-scrollbar {
  z-index: 11;
  width: 6px;
}
.el-input::-webkit-scrollbar:horizontal {
  height: 6px;
}
.el-input::-webkit-scrollbar-thumb {
  border-radius: 5px;
  width: 6px;
  background: #b4bccc;
}
.el-input::-webkit-scrollbar-corner {
  background: #fff;
}
.el-input::-webkit-scrollbar-track {
  background: #fff;
}
.el-input::-webkit-scrollbar-track-piece {
  background: #fff;
  width: 6px;
}
.el-input .el-input__clear {
  color: #96999C;
  cursor: pointer;
  transition: color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.el-input .el-input__count {
  height: 100%;
  display: inline-flex;
  align-items: center;
  color: #96999C;
  font-size: 12px;
}
.el-input .el-input__count .el-input__count-inner {
  background: #FFFFFF;
  line-height: initial;
  display: inline-block;
  padding: 0 5px;
}
.el-input .el-input__count .el-input__count-limit {
  color: #FF4A4D;
}
.el-input__inner {
  -webkit-appearance: none;
  background-color: #FFFFFF;
  background-image: none;
  border-radius: 2px;
  border: 1px solid #B9BABD;
  box-sizing: border-box;
  color: #161C24;
  display: inline-block;
  font-size: inherit;
  height: 28px;
  line-height: 28px;
  outline: none;
  padding: 0 12px;
  transition: border-color 0.2s cubic-bezier(0.645, 0.045, 0.355, 1);
  width: 100%;
}
.el-input__inner::-ms-reveal {
  display: none;
}
.el-input__inner::placeholder {
  color: #C5C6C8;
}
.el-input__inner:hover {
  border-color: #73777C;
}
.el-input__inner:focus {
  outline: none;
  border-color: #0077FF;
}
.el-input__suffix {
  position: absolute;
  height: 100%;
  right: 5px;
  top: 0;
  text-align: center;
  color: #96999C;
  transition: all 0.3s;
  pointer-events: none;
}
.el-input__suffix .el-icon-loading:before {
  color: #96999C;
}
.el-input__suffix .el-icon__danger_color {
  color: #FF4A4D;
}
.el-input__suffix .el-icon__warning_color {
  color: #FAAE16;
}
.el-input__suffix .el-icon__success_color {
  color: #52C718;
}
.el-input__suffix-inner {
  pointer-events: all;
}
.el-input__prefix {
  position: absolute;
  height: 100%;
  left: 5px;
  top: 0;
  text-align: center;
  color: #96999C;
  transition: all 0.3s;
}
.el-input__icon {
  height: 100%;
