}
.el-color-dropdown__main-wrapper::after {
  content: "";
  display: table;
  clear: both;
}
.el-color-dropdown__btns {
  margin-top: 6px;
  text-align: right;
}
.el-color-dropdown__value {
  float: left;
  line-height: 26px;
  font-size: 12px;
  color: #000000;
  width: 160px;
}
.el-color-dropdown__btn {
  border: 1px solid #dcdcdc;
  color: #333;
